export interface ChipRect {
  id: string
  x: number
  y: number
  w: number
  h: number
}

export interface ChipCorners {
  tl: boolean
  tr: boolean
  bl: boolean
  br: boolean
}

export interface ChipBlock {
  /** Joined to the chip physically beside it on the same row (left/right follow the layout, so RTL works). */
  left: boolean
  right: boolean
  /** Joins earlier in this chip's row, in reading order. Each one pulls the rest of the row in by `pull` px. */
  shift: number
  /** Joined to a selected chip in the row above / below. */
  up: boolean
  down: boolean
  /** Rows this chip lifts by, so it stays flush with a lifted chip above it. */
  rows: number
  /** Corners that touch a neighbour and square off. */
  corners: ChipCorners
}

/** Minimum shared edge (px) before chips on adjacent rows count as touching. */
export const MIN_OVERLAP = 12
/** Share of a chip's width the selected chips above must cover before it joins them and lifts. */
export const MIN_COVER = 0.5
/** Tolerance (px) when deciding whether a neighbour covers a corner. */
const EDGE = 1.5

export interface BlockOptions {
  /** How far each join pulls the rest of its row in (px). Visual only: layout never changes. */
  pull?: number
  /** The row runs right-to-left, so the previous chip in reading order sits on the right. */
  rtl?: boolean
  /** Also join chips across wrapped rows. Defaults to true; false joins sideways only. */
  stack?: boolean
}

/**
 * Works out how selected chips join, from their resting layout (rects in DOM
 * order). Joins are drawn with transforms, so they never move the resting
 * layout, never change how the row wraps and never feed back into this
 * measurement. Same-row neighbours join sideways; a selected chip mostly
 * covered by selected chips in the row above joins upward and lifts to meet
 * them, stacking across rows. Pure: no DOM.
 */
export function computeBlocks(
  rects: readonly ChipRect[],
  selected: ReadonlySet<string>,
  options: BlockOptions = {}
): Record<string, ChipBlock> {
  // Chips on one row can only stay joined sideways if they end up at the same height. When
  // one lifts to meet the row above and its neighbour doesn't, split them and measure again.
  // Splits only ever accumulate, so this settles within a few passes.
  const split = new Set<string>()
  for (let pass = 0; pass <= rects.length; pass++) {
    const blocks = layout(rects, selected, options, split)
    const before = split.size
    rects.forEach((r, i) => {
      if (i > 0 && blocks[r.id].shift > blocks[rects[i - 1].id].shift && blocks[r.id].rows !== blocks[rects[i - 1].id].rows) split.add(r.id)
    })
    if (split.size === before) return blocks
  }
  return layout(rects, selected, options, split)
}

function layout(
  rects: readonly ChipRect[],
  selected: ReadonlySet<string>,
  { pull = 0, rtl = false, stack = true }: BlockOptions,
  split: ReadonlySet<string>
): Record<string, ChipBlock> {
  const rowTops = [...new Set(rects.map((r) => Math.round(r.y)))].sort((a, b) => a - b)
  const rowOf = (r: ChipRect) => rowTops.indexOf(Math.round(r.y))
  const isOn = (i: number) => i >= 0 && i < rects.length && selected.has(rects[i].id)

  const blocks: Record<string, ChipBlock> = {}
  rects.forEach((r, i) => {
    const on = isOn(i)
    const joinsPrev = on && isOn(i - 1) && rowOf(rects[i - 1]) === rowOf(r) && !split.has(r.id)
    const joinsNext = on && isOn(i + 1) && rowOf(rects[i + 1]) === rowOf(r) && !split.has(rects[i + 1].id)
    // The previous chip sits on the left unless the row runs right-to-left.
    const left = rtl ? joinsNext : joinsPrev
    const right = rtl ? joinsPrev : joinsNext
    const sameRowAsPrev = i > 0 && rowOf(rects[i - 1]) === rowOf(r)
    const shift = (sameRowAsPrev ? blocks[rects[i - 1].id].shift : 0) + (joinsPrev ? 1 : 0)
    blocks[r.id] = { left, right, shift, up: false, down: false, rows: 0, corners: { tl: left, bl: left, tr: right, br: right } }
  })

  // Where each chip actually sits once its row has been pulled in.
  const seen = new Map(rects.map((r) => [r.id, { ...r, x: r.x + (rtl ? 1 : -1) * blocks[r.id].shift * pull }]))
  const shown = rects.map((r) => seen.get(r.id)!)

  const overlap = (a: ChipRect, b: ChipRect) => Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x)
  // Top row first, so each chip's lift can stack on the lift of the chip above it.
  const chosen = shown.filter((r) => stack && selected.has(r.id)).sort((a, b) => rowOf(a) - rowOf(b) || a.x - b.x)
  for (const r of chosen) {
    const row = rowOf(r)
    const above = chosen.filter((a) => rowOf(a) === row - 1 && overlap(a, r) >= MIN_OVERLAP)
    // A chip only hanging off the edge of the row above stays down, beside its own row.
    if (!above.length || above.reduce((sum, a) => sum + overlap(a, r), 0) < MIN_COVER * r.w) continue
    const me = blocks[r.id]
    me.up = true
    me.rows = 1 + Math.max(...above.map((a) => blocks[a.id].rows))
    if (above.some((a) => a.x <= r.x + EDGE)) me.corners.tl = true
    if (above.some((a) => a.x + a.w >= r.x + r.w - EDGE)) me.corners.tr = true
    for (const a of above) {
      const up = blocks[a.id]
      up.down = true
      if (r.x <= a.x + EDGE) up.corners.bl = true
      if (r.x + r.w >= a.x + a.w - EDGE) up.corners.br = true
    }
  }
  return blocks
}

export type ChipRemoval = "fade" | "collapse" | "blur"
export type ChipClose = "overlap" | "glide" | "inout" | "spring"

export interface RemoveChipOptions {
  removal?: ChipRemoval
  close?: ChipClose
  reducedMotion?: boolean
}

const CALM = "cubic-bezier(.2,.8,.2,1)"

/** A damped spring (ζ < 1 settles with a tiny overshoot) sampled into a CSS `linear()` easing. */
export function springEasing(zeta: number, points = 40): string {
  // Undamped never settles and critically damped has no oscillation to sample; keep both out.
  zeta = Math.min(Math.max(zeta, 0.1), 0.95)
  const w = 12
  const wd = w * Math.sqrt(1 - zeta * zeta)
  const x = (t: number) => 1 - Math.exp(-zeta * w * t) * (Math.cos(wd * t) + ((zeta * w) / wd) * Math.sin(wd * t))
  let end = 0.1
  while (Math.abs(1 - x(end)) > 0.002 || Math.abs(1 - x(end + 0.05)) > 0.002) end += 0.02
  const values = Array.from({ length: points + 1 }, (_, i) => x((i / points) * end).toFixed(4))
  values[points] = "1"
  return `linear(${values.join(", ")})`
}

/**
 * When and how neighbours slide into the gap. `start` is the share of the
 * removal effect that plays before the gap starts closing: overlapping the
 * two (instead of waiting, then snapping) is what keeps it smooth.
 */
export const CLOSE_TIMINGS: Record<ChipClose, { start: number; duration: number; easing: string }> = {
  overlap: { start: 0.5, duration: 440, easing: "cubic-bezier(.45,0,.25,1)" },
  glide: { start: 0.85, duration: 380, easing: "cubic-bezier(.4,0,.2,1)" },
  inout: { start: 0.8, duration: 480, easing: "cubic-bezier(.65,0,.35,1)" },
  spring: { start: 0.75, duration: 560, easing: springEasing(0.72) },
}

const EFFECTS: Record<ChipRemoval, { duration: number; keyframes: Keyframe[] }> = {
  fade: { duration: 200, keyframes: [{ opacity: 1, scale: "1" }, { opacity: 0, scale: "0.92" }] },
  collapse: { duration: 160, keyframes: [{ opacity: 1 }, { opacity: 0 }] },
  blur: {
    duration: 280,
    keyframes: [
      { opacity: 1, filter: "blur(0)", scale: "1" },
      { opacity: 0, filter: "blur(6px)", scale: "1.03" },
    ],
  },
}

/** Milliseconds into the removal effect at which the gap starts closing. */
export function closeStartMs(removal: ChipRemoval, close: ChipClose): number {
  return removal === "collapse" ? 0 : EFFECTS[removal].duration * CLOSE_TIMINGS[close].start
}

export function prefersReducedMotion(): boolean {
  return (
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  )
}

/** Plays a chip's exit, then collapses its width so neighbours slide in. Resolves when both finish. */
export async function removeChip(
  el: HTMLElement,
  { removal = "fade", close = "overlap", reducedMotion = prefersReducedMotion() }: RemoveChipOptions = {}
): Promise<void> {
  el.style.pointerEvents = "none"
  if (reducedMotion) {
    await play(el, [{ opacity: 1 }, { opacity: 0 }], { duration: 120, fill: "forwards" })
    await collapseWidth(el, 0, CALM)
    return
  }
  const effect = EFFECTS[removal]
  const timing = CLOSE_TIMINGS[close]
  const played = play(el, effect.keyframes, { duration: effect.duration, easing: CALM, fill: "forwards" })
  await wait(closeStartMs(removal, close))
  await Promise.all([collapseWidth(el, timing.duration, timing.easing), played])
}

/** `el.animate`, resolving straight away where the Web Animations API is missing (e.g. jsdom) or the animation is cancelled. */
function play(el: HTMLElement, keyframes: Keyframe[], options: KeyframeAnimationOptions): Promise<void> {
  if (typeof el.animate !== "function") return Promise.resolve()
  return el.animate(keyframes, options).finished.then(
    () => undefined,
    () => undefined
  )
}

function wait(ms: number) {
  return new Promise<void>((resolve) => setTimeout(resolve, ms))
}

/** Shrinks the chip to zero width and eats the flex gap; content stays centred while it narrows. */
function collapseWidth(el: HTMLElement, duration: number, easing: string): Promise<void> {
  const gap = el.parentElement ? parseFloat(getComputedStyle(el.parentElement).columnGap) || 0 : 0
  const width = el.getBoundingClientRect().width
  el.style.overflow = "hidden"
  el.style.justifyContent = "center"
  return play(
    el,
    [
      { width: `${width}px`, marginRight: "0px" },
      { width: "0px", marginRight: `${-gap}px`, borderWidth: "0px" },
    ],
    { duration, easing, fill: "forwards" }
  )
}

"use client"

import * as React from "react"
import { CheckIcon } from "lucide-react"
import { ToggleGroup as ToggleGroupPrimitive } from "radix-ui"

import { cn } from "@/lib/utils"
import { computeBlocks, type ChipBlock } from "@/components/ui/chip-layout"

/** `compact` joins neighbours on a row; `block` also joins across wrapped rows; `none` never joins. */
type ChipJoin = "compact" | "block" | "none"

/**
 * Joined chips close the gap down to `--chip-seam`, sideways and between wrapped rows, by
 * transform only: the layout (and so the wrapping) never changes. Set the spacing with
 * `--chip-gap` (not `gap-*`), so the join follows it. `--chip-ease` and `--chip-dur` time the
 * check icon growing and the chips moving together, so the two motions add up to one smooth move.
 */

const ITEM = '[data-slot="chip-group-item"]'
/** How long to keep re-measuring after a change: covers the check icon and margin transitions. */
const FOLLOW_MS = 320

function ChipGroup({
  className,
  join = "compact",
  ref,
  ...props
}: React.ComponentProps<typeof ToggleGroupPrimitive.Root> & { join?: ChipJoin }) {
  const rootRef = React.useRef<HTMLDivElement | null>(null)
  const setRef = React.useCallback(
    (node: HTMLDivElement | null) => {
      rootRef.current = node
      if (typeof ref === "function") ref(node)
      else if (ref) ref.current = node
    },
    [ref]
  )
  useChipJoins(rootRef, join)

  return (
    <ToggleGroupPrimitive.Root
      ref={setRef}
      data-slot="chip-group"
      data-join={join}
      className={cn("relative flex flex-wrap gap-(--chip-gap) [--chip-gap:--spacing(2)] [--chip-seam:2px] [--chip-ease:cubic-bezier(.2,.8,.2,1)] [--chip-dur:200ms]", className)}
      {...props}
      // Every chip is its own Tab stop; Radix's default makes the group one stop with arrow keys.
      rovingFocus={false}
    />
  )
}

function ChipGroupItem({ className, children, ...props }: React.ComponentProps<typeof ToggleGroupPrimitive.Item>) {
  return (
    <ToggleGroupPrimitive.Item
      data-slot="chip-group-item"
      className={cn(
        "group/chip inline-flex h-8 shrink-0 items-center rounded-md border border-input bg-transparent px-3 text-sm font-medium whitespace-nowrap shadow-xs outline-none select-none",
        "transition-[translate,border-radius,background-color,color,padding] duration-(--chip-dur) ease-(--chip-ease) motion-reduce:transition-none",
        "hover:bg-accent/50 focus-visible:z-10 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50",
        "disabled:pointer-events-none disabled:opacity-50",
        "data-[state=on]:bg-accent data-[state=on]:ps-2 data-[state=on]:text-accent-foreground",
        // Compact join: the hook writes how far this chip moves; touching corners soften to 3px.
        "[translate:var(--chip-x,0px)_var(--chip-y,0px)]",
        "data-[corner-tl]:rounded-tl-[3px] data-[corner-tr]:rounded-tr-[3px] data-[corner-bl]:rounded-bl-[3px] data-[corner-br]:rounded-br-[3px]",
        className
      )}
      {...props}
    >
      <CheckIcon
        aria-hidden="true"
        className="h-4 w-0 shrink-0 opacity-0 transition-[width,margin,opacity] duration-(--chip-dur) ease-(--chip-ease) motion-reduce:transition-none group-data-[state=on]/chip:me-1.5 group-data-[state=on]/chip:w-4 group-data-[state=on]/chip:opacity-100"
      />
      {children}
    </ToggleGroupPrimitive.Item>
  )
}

/**
 * Measures the chips' resting layout and writes join attributes onto them.
 * Reads selection from the DOM (`data-state="on"`), so it works for
 * controlled and uncontrolled groups alike.
 */
function useChipJoins(ref: React.RefObject<HTMLElement | null>, join: ChipJoin) {
  React.useLayoutEffect(() => {
    const root = ref.current
    if (!root || join === "none") return
    let raf = 0
    let until = 0
    const apply = () => {
      const style = getComputedStyle(root)
      // The distance each join closes: the resolved gap minus the seam left between joined chips.
      const pull = (parseFloat(style.columnGap) || 0) - (parseFloat(style.getPropertyValue("--chip-seam")) || 0)
      const rtl = style.direction === "rtl"
      const items = Array.from(root.querySelectorAll<HTMLElement>(ITEM))
      const rects = items.map((el, i) => ({ id: String(i), x: el.offsetLeft, y: el.offsetTop, w: el.offsetWidth, h: el.offsetHeight }))
      const selected = new Set(items.flatMap((el, i) => (el.dataset.state === "on" ? [String(i)] : [])))
      const blocks = computeBlocks(rects, selected, { pull, rtl, stack: join === "block" })
      items.forEach((el, i) => writeJoin(el, blocks[String(i)], pull * (rtl ? 1 : -1)))
    }
    const follow = () => {
      apply()
      if (performance.now() < until) raf = requestAnimationFrame(follow)
    }
    const kick = () => {
      until = performance.now() + FOLLOW_MS
      cancelAnimationFrame(raf)
      follow()
    }
    kick()
    const resize = new ResizeObserver(kick)
    resize.observe(root)
    const mutation = new MutationObserver(kick)
    mutation.observe(root, { subtree: true, childList: true, attributes: true, attributeFilter: ["data-state", "dir"] })
    return () => {
      cancelAnimationFrame(raf)
      resize.disconnect()
      mutation.disconnect()
      root.querySelectorAll<HTMLElement>(ITEM).forEach((el) => writeJoin(el, undefined))
    }
  }, [ref, join])
}

/** `step` is the signed px one join moves a chip sideways; a row lifts by one `pull` per row. */
function writeJoin(el: HTMLElement, block: ChipBlock | undefined, step = 0) {
  el.toggleAttribute("data-corner-tl", !!block?.corners.tl)
  el.toggleAttribute("data-corner-tr", !!block?.corners.tr)
  el.toggleAttribute("data-corner-bl", !!block?.corners.bl)
  el.toggleAttribute("data-corner-br", !!block?.corners.br)
  setPx(el, "--chip-x", block?.shift && step ? block.shift * step : 0)
  setPx(el, "--chip-y", block?.rows && step ? block.rows * -Math.abs(step) : 0)
}

function setPx(el: HTMLElement, name: string, px: number) {
  if (px) el.style.setProperty(name, `${px}px`)
  else el.style.removeProperty(name)
}

export { ChipGroup, ChipGroupItem, type ChipJoin }

"use client"

import * as React from "react"
import { XIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { prefersReducedMotion, removeChip, type ChipClose, type ChipRemoval } from "@/components/ui/chip-motion"

interface ChipListItem {
  value: string
  label: string
  icon?: React.ReactNode
}

interface ChipListProps extends Omit<React.ComponentProps<"ul">, "children"> {
  items: ChipListItem[]
  onRemove: (value: string) => void
  removal?: ChipRemoval
  close?: ChipClose
  /** Defaults to the OS "reduce motion" setting. */
  reducedMotion?: boolean
  /** Where focus goes when the last chip is removed (e.g. the composer). */
  getFallbackFocus?: () => HTMLElement | null
  /** Classes for each chip, so a kit can restyle them. */
  itemClassName?: string
  messages?: { added?: (label: string) => string; removed?: (label: string) => string }
}

/**
 * A rendered chip. `leaving` chips are playing their exit; they keep their
 * place and key until it ends. A chip re-added while its old element is still
 * leaving gets a new key, so React builds a fresh element beside the spent one.
 */
interface Entry {
  item: ChipListItem
  key: string
  leaving: boolean
}

const toEntry = (item: ChipListItem): Entry => ({ item, key: item.value, leaving: false })
const added = (label: string) => `Added ${label}`
const removed = (label: string) => `Removed ${label}`

/** Live chips follow `items` (current label, icon and order); leaving chips are spliced back where they were. */
function mergeEntries(shown: Entry[], items: ChipListItem[]): Entry[] {
  const liveKey = new Map(shown.filter((s) => !s.leaving).map((s) => [s.item.value, s.key]))
  const freshKey = (value: string) => {
    let key = value
    while (shown.some((s) => s.key === key)) key += "\u0000"
    return key
  }
  const next: Entry[] = items.map((item) => ({ item, key: liveKey.get(item.value) ?? freshKey(item.value), leaving: false }))
  shown.forEach((s, index) => {
    if (s.leaving || !items.some((i) => i.value === s.item.value)) next.splice(Math.min(index, next.length), 0, { ...s, leaving: true })
  })
  return next
}

function ChipList({
  items,
  onRemove,
  removal = "fade",
  close = "overlap",
  reducedMotion,
  getFallbackFocus,
  itemClassName,
  messages,
  className,
  ...props
}: ChipListProps) {
  // What's on screen, in order: current items plus any still playing their exit.
  const [shown, setShown] = React.useState(() => items.map(toEntry))
  const [prevItems, setPrevItems] = React.useState(items)
  // `count` makes each announcement a real DOM change, even when the text repeats.
  const [announcement, setAnnouncement] = React.useState({ text: "", count: 0 })
  const elements = React.useRef(new Map<string, HTMLLIElement>())
  const started = React.useRef(new Set<string>())

  // When `items` changes, adjust state during render (no effect, no cascade)
  // and announce the change. Never runs on first mount, so nothing is announced then.
  if (items !== prevItems) {
    setPrevItems(items)
    setShown(mergeEntries(shown, items))
    const parts = [
      ...items.filter((i) => !prevItems.some((p) => p.value === i.value)).map((i) => (messages?.added ?? added)(i.label)),
      ...prevItems.filter((p) => !items.some((i) => i.value === p.value)).map((p) => (messages?.removed ?? removed)(p.label)),
    ]
    if (parts.length) setAnnouncement((a) => ({ text: parts.join(". "), count: a.count + 1 }))
  }

  React.useLayoutEffect(() => {
    for (const entry of shown) {
      if (!entry.leaving || started.current.has(entry.key)) continue
      const el = elements.current.get(entry.key)
      if (!el) continue
      started.current.add(entry.key)
      if (el.contains(document.activeElement)) {
        // Next live chip, else previous, else the fallback, else the list itself — never <body>.
        const order = shown.filter((s) => s.key === entry.key || !s.leaving)
        const at = order.findIndex((s) => s.key === entry.key)
        const target = order[at + 1] ?? order[at - 1]
        const next = target ? elements.current.get(target.key)?.querySelector("button") : (getFallbackFocus?.() ?? el.parentElement)
        next?.focus()
      }
      el.inert = true
      removeChip(el, { removal, close, reducedMotion: reducedMotion ?? prefersReducedMotion() }).then(() => {
        started.current.delete(entry.key)
        setShown((s) => s.filter((x) => x.key !== entry.key))
      })
    }
  }, [shown, removal, close, reducedMotion, getFallbackFocus])

  return (
    <>
      {/* tabIndex -1: focus lands here when the last chip goes and there's no fallback. */}
      <ul data-slot="chip-list" tabIndex={-1} className={cn("flex min-h-7 flex-wrap gap-1.5 outline-none", className)} {...props}>
        {shown.map(({ item, key }) => (
          <li
            key={key}
            data-slot="chip-list-item"
            ref={(el) => {
              if (!el) return
              elements.current.set(key, el)
              return () => {
                elements.current.delete(key)
              }
            }}
            className={cn(
              "inline-flex h-7 shrink-0 rounded-md border bg-secondary text-secondary-foreground",
              !reducedMotion && "motion-safe:animate-[chip-in_160ms_cubic-bezier(.2,.8,.2,1)]",
              itemClassName
            )}
          >
            <button
              type="button"
              aria-label={`Remove ${item.label}`}
              onClick={() => onRemove(item.value)}
              className="group/chip inline-flex h-full shrink-0 items-center gap-1 rounded-[inherit] pr-1.5 pl-2.5 text-xs font-medium whitespace-nowrap outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
            >
              {item.icon}
              <span>{item.label}</span>
              <XIcon aria-hidden="true" className="size-3.5 text-muted-foreground transition-colors group-hover/chip:text-foreground" />
            </button>
          </li>
        ))}
      </ul>
      <span role="status" aria-live="polite" className="sr-only">
        {announcement.text}
        {announcement.count % 2 ? "\u200b" : ""}
      </span>
    </>
  )
}

export { ChipList, type ChipListItem, type ChipListProps }
